'use client';
import { useEffect, useRef, useState } from 'react';
import { PhaserGame } from '@/game/PhaserGame';

export default function GameCanvas() {
  const gameRef = useRef<PhaserGame | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const initPhaser = async () => {
      if (!navigator.gpu) console.warn('WebGPU não disponível');
      const game = new PhaserGame();
      await game.init('phaser-container');
      gameRef.current = game;
      setIsLoading(false);
    };

    if (typeof window !== 'undefined' && !gameRef.current) initPhaser();

    return () => {
      gameRef.current?.destroy();
      gameRef.current = null;
    };
  }, []);

  return (
    <div id='phaser-container' ref={containerRef} className='w-full h-full' />
  );
}

