import Phaser from 'phaser';

export interface MapData {
  width: number;
  height: number;
  tiles: number[];
  terrain: number[][];
}

export class TilemapRenderer {
  private scene: Phaser.Scene;
  private tilemap!: Phaser.Tilemaps.Tilemap;
  private layers: Phaser.Tilemaps.TilemapLayer[] = [];

  constructor(scene: Phaser.Scene) {
    this.scene = scene;
  }

  createFromData(mapData: MapData): void {
    this.tilemap = this.scene.make.tilemap({
      tileWidth: 32,
      tileHeight: 32,
      width: mapData.width,
      height: mapData.height,
    });

    const tileset = this.tilemap.addTilesetImage(
      'world_tiles',
      undefined,
      32, 32,
      0, 0
    );

    const layer = this.tilemap.createBlankLayer('base', tileset);

    for (let y = 0; y < mapData.height; y++) {
      for (let x = 0; x < mapData.width; x++) {
        const tileId = mapData.tiles[y * mapData.width + x];
        if (tileId > 0) {
          layer.putTileAt(tileId - 1, x, y);
        }
      }
    }

    this.layers.push(layer);
  }

  getTileAt(x: number, y: number): Phaser.Tilemaps.Tile | null {
    return this.tilemap.getTileAt(x, y, false, 'base');
  }

  setTile(tileId: number, x: number, y: number): void {
    this.layers[0]?.putTileAt(tileId - 1, x, y);
  }
}

