class CameraController extends Phaser.Scene {
  private camera: Phaser.Cameras.SceneCamera;
  private panSpeed = 500;

  update(time: number, delta: number) {
    const speed = this.panSpeed * (delta / 1000);
    if (this.keys.left.isDown) this.camera.scrollX -= speed;
    if (this.keys.right.isDown) this.camera.scrollX += speed;
  }
}

camera_controller.content:
export class CameraController {
  private camera: Phaser.Cameras.Scene2D.Camera;
  private isDragging: boolean = false;
  private dragStartX: number = 0;
  private dragStartY: number = 0;
  private cameraStartX: number = 0;
  private cameraStartY: number = 0;
  private minZoom: number = 0.25;
  private maxZoom: number = 3.0;

  constructor(camera: Phaser.Cameras.Scene2D.Camera, scene: Phaser.Scene) {
    this.camera = camera;

    scene.input.on('pointerdown', this.onPointerDown, this);
    scene.input.on('pointermove', this.onPointerMove, this);
    scene.input.on('pointerup', this.onPointerUp, this);
    scene.input.on('pointerupoutside', this.onPointerUp, this);
    scene.input.on('wheel', this.onWheel, this);
  }

  private onPointerDown(pointer: Phaser.Input.Pointer): void {
    if (pointer.leftButtonDown()) {
      this.isDragging = true;
      this.dragStartX = pointer.x;
      this.dragStartY = pointer.y;
      this.cameraStartX = this.camera.scrollX;
      this.cameraStartY = this.camera.scrollY;
    }
  }

  private onPointerMove(pointer: Phaser.Input.Pointer): void {
    if (this.isDragging) {
      const deltaX = (this.dragStartX - pointer.x) / this.camera.zoom;
      const deltaY = (this.dragStartY - pointer.y) / this.camera.zoom;
      this.camera.scrollX = this.cameraStartX + deltaX;
      this.camera.scrollY = this.cameraStartY + deltaY;
    }
  }

  private onPointerUp(): void {
    this.isDragging = false;
  }

  private onWheel(
    pointer: Phaser.Input.Pointer,
    _gameObjects: Phaser.GameObjects.GameObject[],
    _deltaX: number,
    deltaY: number
  ): void {
    const worldPoint = this.camera.getWorldPoint(pointer.x, pointer.y);
    const zoomFactor = 0.001 * deltaY;
    const newZoom = this.camera.zoom - this.camera.zoom * zoomFactor;
    this.camera.zoom = Phaser.Math.Clamp(newZoom, this.minZoom, this.maxZoom);
    const newWorldPoint = this.camera.getWorldPoint(pointer.x, pointer.y);
    this.camera.scrollX += worldPoint.x - newWorldPoint.x;
    this.camera.scrollY += worldPoint.y - newWorldPoint.y;
  }
}

