import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

interface TimeState {
  day: number;
  month: number;
  year: number;
}

interface GameState {
  time: TimeState;
  playerCountry: string | null;
  treasury: number;
  isPaused: boolean;
  gameSpeed: number;
  advanceTime: (days: number) => void;
  setPaused: (paused: boolean) => void;
  setGameSpeed: (speed: number) => void;
  setPlayerCountry: (countryId: string) => void;
  modifyTreasury: (amount: number) => void;
}

export const useGameStore = create<GameState>()(
  persist(
    (set) => ({
      time: { day: 1, month: 1, year: 1836 },
      playerCountry: null,
      treasury: 1000,
      isPaused: true,
      gameSpeed: 0,

      advanceTime: (days) => set((state) => {
        let newDay = state.time.day + days;
        let newMonth = state.time.month;
        let newYear = state.time.year;

        while (newDay > 30) {
          newDay -= 30;
          newMonth++;
          if (newMonth > 12) {
            newMonth = 1;
            newYear++;
          }
        }

        return { time: { day: newDay, month: newMonth, year: newYear } };
      }),

      setPaused: (paused) => set({ isPaused: paused }),
      setGameSpeed: (speed) => set({ 
        gameSpeed: speed, 
        isPaused: speed === 0 
      }),
      setPlayerCountry: (id) => set({ playerCountry: id }),
      modifyTreasury: (amount) => set((state) => ({
        treasury: Math.max(0, state.treasury + amount)
      })),
    }),
    {
      name: 'game-save',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        time: state.time,
        playerCountry: state.playerCountry,
        treasury: state.treasury,
      }),
    }
  )
);

